toolArgs.file_text:
/* ── Layout ── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #1a1d21;
    color: #d1d2d3;
}

/* ── Left sidebar ── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #19171d;
    border-right: 1px solid #333;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #333;
}

.sidebar-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #27242c;
}

.channel-item.active {
    background: #1164a3;
    border-left-color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #fff;
}

.channel-desc {
    font-size: 0.75rem;
    color: #9a9b9e;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 10px;
    right: 12px;
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
    padding: 1px 7px;
    font-size: 0.7rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

/* ── Main message area ── */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #1a1d21;
    min-width: 0;
}

.message-area.thread-open {
    /* Shrinks to ~55% automatically when thread panel appears */
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #9a9b9e;
    font-size: 1.1rem;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #333;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.15rem;
    color: #fff;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #9a9b9e;
}

/* ── Message list ── */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #9a9b9e;
    font-size: 0.85rem;
}

.message-row {
    padding: 8px 12px;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
}

.message-row:hover {
    background: #222529;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #fff;
}

.timestamp {
    font-size: 0.7rem;
    color: #717274;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    word-break: break-word;
}

/* ── Reactions ── */
.reaction-row {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2c2d30;
    border: 1px solid #444;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #d1d2d3;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #3a3b3f;
    border-color: #6a6b6e;
}

/* ── Thread starter link ── */
.thread-link {
    background: none;
    border: none;
    color: #1d9bd1;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0 0;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Hover action buttons ── */
.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #1a1d21;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,.4);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    color: #d1d2d3;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background: #2c2d30;
}

/* ── Emoji picker ── */
.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: #2c2d30;
    border: 1px solid #444;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 4px;
    box-shadow: 0 4px 12px rgba(0,0,0,.5);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #3a3b3f;
}

/* ── Message input ── */
.message-input-area {
    padding: 12px 20px;
    border-top: 1px solid #333;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input-area textarea {
    flex: 1;
    background: #222529;
    border: 1px solid #444;
    border-radius: 6px;
    color: #d1d2d3;
    padding: 8px 12px;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
    outline: none;
}

.message-input-area textarea:focus {
    border-color: #1d9bd1;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #148567;
}

.send-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

/* ── Thread panel ── */
.thread-panel {
    width: 25%;
    min-width: 280px;
    border-left: 1px solid #333;
    background: #19171d;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #333;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-thread-btn {
    background: none;
    border: none;
    color: #9a9b9e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #2c2d30;
    color: #fff;
}

.thread-root-quote {
    padding: 12px 16px;
    background: #222529;
    border-bottom: 1px solid #333;
    flex-shrink: 0;
}

.thread-root-quote .author {
    font-size: 0.85rem;
}

.thread-root-quote .timestamp {
    margin-left: 6px;
}

.thread-root-quote p {
    margin: 6px 0 0;
    font-size: 0.85rem;
    line-height: 1.4;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 16px;
}

.thread-replies .message-row {
    padding: 6px 8px;
}

.thread-panel .message-input-area {
    padding: 12px 16px;
}

